const system = `You extract data from bank statements (Kontoauszug, Umsatzübersicht or similar), in German or English.
Return ONLY valid JSON, no other text.

Rules:
- If the text is not a bank statement, return only: {"is_statement": false}
- Dates as YYYY-MM-DD
- Amounts as numbers with a dot (e.g. 1234.56)
- Debits negative, credits positive
- Keep payee and description exactly as written
- normalised_payee: the short, clean company name (e.g. "SEPA-LASTSCHRIFT VATTENF." -> "Vattenfall")
- is_reversal: true for returned debits (Rücklastschrift), refunds or cancellations (Storno), otherwise false
- account_id: the IBAN masked as first 4 + last 4 characters (e.g. "DE00****0000")
- Give each transaction one category from this list only:
  rent, energy, telecom, insurance, broadcasting_fee,
  streaming, music, fitness, apps, transport,
  groceries, drugstore, shopping, food_delivery, travel,
  salary, pension, student_aid, child_benefit,
  interest, transfer, education, memberships, donations, news_media, other
- education = Kita/daycare, school (lunch, trips, fees), university/semester fees, music or tutoring lessons; memberships = clubs, associations, ADAC; donations = charities; news_media = newspapers and magazines.
- child_benefit: Kindergeld from the Familienkasse
- interest: Zinsen (account interest)
- transfer: Umbuchung between own accounts, or money from private persons
- If unsure, use "other"`;

const user = `Extract all data from this statement in this format:
{
  "is_statement": true,
  "bank": "",
  "account_id": "",
  "account_holder": "",
  "period_start": "",
  "period_end": "",
  "opening_balance": 0,
  "closing_balance": 0,
  "transactions": [
    {"date": "", "type": "", "payee": "", "normalised_payee": "",
     "description": "", "amount": 0, "category": "", "is_reversal": false}
  ]
}

Statement text:
` + $json.text;

return {
  json: {
    body: {
      model: "claude-sonnet-5-5",
      max_tokens: 4000,
      system: system,
      messages: [{ role: "user", content: user }]
    }
  }
};

const crypto = require('crypto');

const ALLOWED = new Set(["rent", "energy", "telecom", "insurance", "broadcasting_fee",
  "streaming", "music", "fitness", "apps", "transport",
  "groceries", "drugstore", "shopping", "food_delivery", "travel",
  "salary", "pension", "student_aid", "child_benefit",
  "interest", "transfer", "education", "memberships", "donations", "news_media", "other"]);

const makeKey = (...parts) =>
  crypto.createHash('sha256').update(parts.map(String).join('|')).digest('hex');
const cents = (x) => Math.round(Number(x) * 100);

// File details from the trigger. The name must match your trigger node EXACTLY.
const trigger = $('Trigger – New statement uploaded').item.json;
const fileInfo = { file_id: trigger.id, file_name: trigger.name };
const fail = (reason, extra = {}) =>
  ({ json: { ...fileInfo, is_valid: false, failure_reason: reason, ...extra } });


// 1. Was Claude's answer complete and readable?
if ($json.stop_reason === "max_tokens") {
  return fail("incomplete_response", { note: "answer cut off (max_tokens)" });
}
let text = (($json.content || []).find(b => b.type === "text")?.text || "").trim();
const start = text.indexOf("{");
const end = text.lastIndexOf("}");
let data;
try {
  data = JSON.parse(text.slice(start, end + 1));
} catch (e) {
  return fail("incomplete_response", { note: "could not read JSON", error: e.message,
                                       preview: text.slice(0, 300) });
}

// 2. Wrong file
if (data.is_statement === false) return fail("not_a_statement");

// 3. Required fields and at least one transaction
const required = ["period_start", "period_end", "opening_balance", "closing_balance", "transactions"];
if (required.some(f => data[f] === undefined || data[f] === null || data[f] === "") ||
    !Array.isArray(data.transactions) || data.transactions.length === 0) {
  return fail("missing_fields");
}

// 4. Account found? Mask IBAN (guaranteed)
const raw = String(data.account_id || "").replace(/\s/g, "");
if (raw.length < 8) return fail("missing_account");
const account_id = raw.slice(0, 4) + "****" + raw.slice(-4);

// 5. Balances add up? (compared in cents to avoid rounding issues)
const total = data.transactions.reduce((s, t) => s + cents(t.amount), 0);
const expected = cents(data.closing_balance) - cents(data.opening_balance);
const is_valid = total === expected;

// Keys (transaction key uses the RAW payee, so Claude's spelling can't create duplicates)
const statement_key = makeKey(account_id, data.period_start, data.period_end,
                              data.opening_balance, data.closing_balance);
const seen = {};
for (const t of data.transactions) {
  t.normalised_payee = t.normalised_payee || t.payee;
  t.is_reversal = Boolean(t.is_reversal);
  t.category = ALLOWED.has(t.category) ? t.category : "other";
  const base = [account_id, t.date, t.payee, t.amount, t.description || ""].join('|');
  seen[base] = (seen[base] || 0) + 1;
  t.idempotency_key = makeKey(base, seen[base]);
}

return {
  json: {
    ...fileInfo,
     is_valid: is_valid,
    failure_reason: is_valid ? "" : "balance_mismatch",
    statement_key,
    account_id,
    period_start: data.period_start,
    period_end: data.period_end,
    opening_balance: data.opening_balance,
    closing_balance: data.closing_balance,
    transaction_count: data.transactions.length,
    transactions: data.transactions
  }
};

